css:
/* A4, measured from the paper original. Top-level .print-format margins are the
   wkhtmltopdf page margins (Frappe reads them); "Page N of 4" is stamped onto the
   PDF by wahni_solar_proposal/proposal_pdf.py. */
.print-format {
    margin-top: 25mm;
    margin-bottom: 30mm;
    margin-left: 25mm;
    /* 2mm less than the layout margin; see the print padding below */
    margin-right: 23mm;
    padding: 0 !important;
    font-family: "Times New Roman", "Liberation Serif", serif;
    font-size: 11pt;
    line-height: 19pt;
    color: #000;
}
/* Frappe reads only the top-level rule above; don't apply it again inside the page.
   The 2mm right inset absorbs wkhtmltopdf drawing text slightly wider than it laid it out,
   which otherwise clips the last letters of full-width lines at the page margin. */
@media print {
    .print-format { margin: 0 !important; }
    .document-page { padding-right: 2mm; }
}
.document-page { position: relative; }
.document-page + .document-page { page-break-before: always; }
/* page 1 leaves the top of the sheet blank for the stamp paper */
.document-page.stamp { padding-top: 147mm; }
.document-page p { margin: 0 0 2.1mm; text-align: justify; }
.document-page .title { font-weight: bold; text-decoration: underline; text-align: left; }
.document-page .center { text-align: center; }
.document-page.tight, .document-page .tight { line-height: 14pt; }
.document-page .gap-8 { margin-bottom: 8.5mm; }
.document-page .gap-10 { margin-bottom: 10.6mm; }
/* numbered clauses: number in the gutter, wrapped lines aligned with the text */
.document-page .item { padding-left: 6.4mm; }
.document-page .item .n { display: inline-block; width: 6.4mm; margin-left: -6.4mm; }
.document-page .signatures { width: 100%; border-collapse: collapse; margin-top: 8.9mm; line-height: 14pt; }
.document-page .signatures td { padding: 0 !important; border: 0; vertical-align: top !important; }
.document-page .signatures td:first-child { width: 92.1mm; }
.document-page .signatures tr + tr td { padding-top: 1.8mm !important; }
.document-page .signatures tr.next td { padding-top: 8.9mm !important; }
.document-page .page-no { display: none; }
/* Browser preview: each page as an A4 sheet with the same margins. */
@media screen {
    .print-format {
        width: 210mm; max-width: none; min-height: 0;
        margin: 0 auto !important;
        background: transparent !important; box-shadow: none !important; border-radius: 0;
    }
    .document-page {
        box-sizing: border-box;
        width: 210mm;
        min-height: 297mm;
        padding: 25mm 25mm 30mm;
        margin: 0 auto 8mm;
        background: #fff;
        box-shadow: 0 1px 6px rgba(0, 0, 0, .25);
    }
    .document-page.stamp { padding-top: 172mm; }
    .document-page .page-no {
        display: block; position: absolute; left: 0; right: 0; top: 262.8mm;
        text-align: center; font-size: 12pt; line-height: 1;
    }
}
